namespace gui_forms {

// PieChart's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/pie_chart.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The hole's radius as a percentage of the pie's (Windows Forms' DoughnutRadius), from 0 (a pie) to maximum_doughnut_radius; outside throws std::invalid_argument.
template <typename Declaring>
struct PieChartDoughnutRadiusCapability {
    PropertyCell<double, PieChartDoughnutRadiusCapability<Declaring>> doughnut_radius{0.0};

    static void assign(PieChartDoughnutRadiusCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.doughnut_radius), incoming);
        if (!capability.doughnut_radius.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.doughnut_radius));
    }
};

// Where the first slice starts, in degrees clockwise from the top (Windows Forms' PieStartAngle), from 0 to below 360; outside throws std::invalid_argument.
template <typename Declaring>
struct PieChartStartAngleCapability {
    PropertyCell<double, PieChartStartAngleCapability<Declaring>> start_angle{0.0};

    static void assign(PieChartStartAngleCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.start_angle), incoming);
        if (!capability.start_angle.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.start_angle));
    }
};

// Where each slice's share is written (Windows Forms' PieLabelStyle).
template <typename Declaring>
struct PieChartLabelStyleCapability {
    PropertyCell<PieChartLabelStyle, PieChartLabelStyleCapability<Declaring>> label_style{PieChartLabelStyle::inside};

    static void assign(PieChartLabelStyleCapability& capability, PieChartLabelStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.label_style), incoming);
        if (!capability.label_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.label_style));
    }
};

// Whether the legend beside the pie lists the slices with their colours.
template <typename Declaring>
struct PieChartLegendVisibleCapability {
    PropertyCell<bool, PieChartLegendVisibleCapability<Declaring>> legend_visible{true};

    static void assign(PieChartLegendVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.legend_visible), incoming);
        if (!capability.legend_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.legend_visible));
    }
};

// PieChartLabelStyle as a property value; defined beside PieChart's table.
template <>
struct PropertyValueTraits<PieChartLabelStyle> {
    static PropertyType type();
    static BindingValue to_binding(PieChartLabelStyle value);
    static PieChartLabelStyle from_binding(const BindingValue& value);
};

// Every PieChart capability, in the order the declaring class takes them.
template <typename Declaring>
struct PieChartCapabilities : public PieChartDoughnutRadiusCapability<Declaring>,
                              public PieChartStartAngleCapability<Declaring>,
                              public PieChartLabelStyleCapability<Declaring>,
                              public PieChartLegendVisibleCapability<Declaring>,
                              public FontCapability<Declaring> {
    PieChartCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 10.5, 400, false}) {}
};

} // namespace gui_forms
